const crypto = require('crypto');
const text = $input.item.json.text || '';
const hash = crypto.createHash('sha256').update(text).digest('hex');

return {
  resume_text: text,
  resume_hash: hash
};

const text = $input.item.json.resume_text || '';

// Word count
const wordCount = text.split(/\s+/).filter(w => w.length > 0).length;

// Character count
const charCount = text.length;

// Check for key sections (case-insensitive)
const lowerText = text.toLowerCase();
const hasSkillsSection = /skills?|technical|competencies|expertise/.test(lowerText);
const hasExperienceSection = /experience|employment|work history|professional/.test(lowerText);
const hasEducationSection = /education|academic|qualification|degree/.test(lowerText);

// Formatting quality indicators
const hasEmail = /@/.test(text);
const hasPhone = /\+?\d{1,4}[\s.-]?\(?\d{1,4}\)?[\s.-]?\d{1,4}[\s.-]?\d{1,9}/.test(text);
const hasBulletPoints = /[•●○■□▪▫–-]/.test(text) || /^\s*[-*]\s/m.test(text);

// Calculate section completeness score (0-3)
const sectionScore = (hasSkillsSection ? 1 : 0) + (hasExperienceSection ? 1 : 0) + (hasEducationSection ? 1 : 0);

// Calculate formatting score (0-3)
const formattingScore = (hasEmail ? 1 : 0) + (hasPhone ? 1 : 0) + (hasBulletPoints ? 1 : 0);

// Overall quality score (0-100)
const qualityScore = Math.round(
  (wordCount >= 600 ? 40 : wordCount >= 300 ? 25 : wordCount >= 100 ? 10 : 0) +
  (sectionScore / 3 * 30) +
  (formattingScore / 3 * 30)
);

// Determine readability category
let readability = 'Poor';
if (qualityScore >= 70) readability = 'Good';
else if (qualityScore >= 40) readability = 'Average';

return {
  ...($input.item.json),
  readability,
  word_count: wordCount,
  char_count: charCount,
  has_skills_section: hasSkillsSection,
  has_experience_section: hasExperienceSection,
  has_education_section: hasEducationSection,
  has_email: hasEmail,
  has_phone: hasPhone,
  has_bullet_points: hasBulletPoints,
  section_completeness_score: sectionScore,
  formatting_score: formattingScore,
  quality_score: qualityScore
};

const crypto = require('crypto');
const text = $input.item.json.text || '';
const hash = crypto.createHash('sha256').update(text).digest('hex');

const resumeData = $('Resume Readability Check').item.json;

return {
  ...resumeData,
  jd_text: text,
  jd_hash: hash
};

// Quality Check & Manual Review Logic
// Retrieve data from Resume Readability Check node
const resumeReadabilityData = $('Resume Readability Check').item.json;
const resumeText = resumeReadabilityData.resume_text || '';
const wordCount = resumeReadabilityData.word_count || 0;
const readability = resumeReadabilityData.readability || '';

// Get current item data from Calculate ATS Score
const confidence = $json.confidence || '';
const candidateName = $json.candidate_name || '';
const email = $json.email || '';
const skills = $json.skills || [];
const resumeHash = $json.resume_hash || '';
const jdHash = $json.jd_hash || '';

let qualityFlag = 'OK';
let qualityReasons = [];
let manualReviewRequired = false;

// 1. Check word count
if (wordCount < 200) {
  qualityReasons.push('Word count is below 200 (insufficient content for reliable parsing)');
  manualReviewRequired = true;
}

// 2. Check readability
if (readability === 'Poor') {
  qualityReasons.push('Resume readability is poor (may indicate formatting issues or low-quality content)');
  manualReviewRequired = true;
}

// 3. Check if resume text is empty or very short
if (!resumeText || resumeText.trim().length < 100) {
  qualityReasons.push('Resume text is empty or very short (less than 100 characters)');
  manualReviewRequired = true;
}

// 4. Check ATS score confidence
if (confidence === 'Low') {
  qualityReasons.push('ATS score confidence is low (automated evaluation may be unreliable)');
  manualReviewRequired = true;
}

// 5. Check for missing critical fields
const missingFields = [];
if (!candidateName || candidateName.trim() === '') {
  missingFields.push('candidate name');
}
if (!email || email.trim() === '') {
  missingFields.push('email');
}
if (!skills || skills.length === 0) {
  missingFields.push('skills');
}

if (missingFields.length > 0) {
  qualityReasons.push(`Critical fields missing from parsed data: ${missingFields.join(', ')}`);
  manualReviewRequired = true;
}

// Set quality flag based on manual review requirement
if (manualReviewRequired) {
  qualityFlag = 'Manual Review Required';
} else {
  qualityFlag = 'OK';
}

const qualityReason = qualityReasons.length > 0 
  ? qualityReasons.join('; ') 
  : 'Resume quality acceptable for automated evaluation';

// Return all existing fields plus new quality fields
return {
  ...$json,
  quality_flag: qualityFlag,
  quality_reason: qualityReason,
  manual_review_required: manualReviewRequired,
  resume_hash: resumeHash,
  jd_hash: jdHash
};

// ===== ENHANCED ATS SCORING WITH INTELLIGENT SKILL CATEGORIZATION =====

// 1. Get data from merged inputs
const resumeData = $json.output_1 || $json.output || $json;
const jdData = $json.output_2 || $json.output || $json;

const resumeSkillsRaw = resumeData.skills || [];
const jdSkillsRaw = jdData.required_skills || [];
const jobTitle = (jdData.job_title || '').toLowerCase();
const requiredExperience = jdData.required_experience_years || 0;

// 2. Force arrays
const resumeSkills = Array.isArray(resumeSkillsRaw)
  ? resumeSkillsRaw
  : resumeSkillsRaw.split(',');

const jdSkills = Array.isArray(jdSkillsRaw)
  ? jdSkillsRaw
  : jdSkillsRaw.split(',');

// 3. Skill synonym mapping for better matching
const skillSynonyms = {
  'javascript': ['js', 'ecmascript', 'node.js', 'nodejs'],
  'python': ['py'],
  'sql': ['mysql', 'postgresql', 'postgres', 'tsql', 'plsql', 'advanced sql'],
  'r': ['r programming', 'r language'],
  'looker studio': ['google data studio', 'data studio'],
  'google sheets': ['sheets', 'excel', 'spreadsheets'],
  'metabase': ['bi tool', 'business intelligence'],
  'r shiny': ['shiny', 'shiny app']
};

// 4. Skill level qualifiers to remove for fuzzy matching
const skillLevelQualifiers = [
  'advanced', 'basic', 'intermediate', 'senior', 'junior',
  'expert', 'beginner', 'proficient', 'experienced'
];

// 5. Enhanced normalize function
const normalize = (skill) => {
  let normalized = skill.toLowerCase().replace(/[-_]/g, ' ').trim();

  skillLevelQualifiers.forEach(qualifier => {
    const regex = new RegExp(`\\b${qualifier}\\b\\s*`, 'gi');
    normalized = normalized.replace(regex, '').trim();
  });

  for (const [key, synonyms] of Object.entries(skillSynonyms)) {
    if (normalized === key || synonyms.includes(normalized)) {
      return key;
    }
  }

  return normalized;
};

// 6. Normalize both sides
const resumeNormalized = resumeSkills.map(normalize);
const jdNormalized = jdSkills.map(normalize);

// 7. INTELLIGENT SKILL CATEGORIZATION LOGIC
// Define industry-specific core skills
const industryMustHaveSkills = {
  'data': ['sql', 'python', 'r'],
  'analyst': ['sql', 'python', 'r'],
  'engineer': ['python', 'sql'],
  'scientist': ['python', 'r', 'sql'],
  'developer': ['javascript', 'python'],
  'frontend': ['javascript', 'html', 'css'],
  'backend': ['python', 'sql', 'java'],
  'fullstack': ['javascript', 'python', 'sql']
};

// Categorize skills intelligently
const mustHaveSkills = [];
const goodToHaveSkills = [];
const optionalSkills = [];

jdNormalized.forEach(skill => {
  let isMustHave = false;

  // Check if skill matches industry core skills
  for (const [role, coreSkills] of Object.entries(industryMustHaveSkills)) {
    if (jobTitle.includes(role) && coreSkills.includes(skill)) {
      isMustHave = true;
      break;
    }
  }

  // SQL is MUST_HAVE for any data-related role
  if ((jobTitle.includes('data') || jobTitle.includes('analyst') || jobTitle.includes('scientist')) 
      && skill === 'sql') {
    isMustHave = true;
  }

  // Python/R are MUST_HAVE for data roles
  if ((jobTitle.includes('data') || jobTitle.includes('analyst')) 
      && (skill === 'python' || skill === 'r')) {
    isMustHave = true;
  }

  // Programming languages are typically MUST_HAVE for technical roles
  const programmingLanguages = ['python', 'javascript', 'java', 'r', 'sql', 'c++', 'c#', 'go', 'rust'];
  if (programmingLanguages.includes(skill) && !isMustHave) {
    // If it's a programming language and appears in first half of skills, it's GOOD_TO_HAVE
    const skillIndex = jdNormalized.indexOf(skill);
    if (skillIndex < jdNormalized.length / 2) {
      goodToHaveSkills.push(skill);
      return;
    }
  }

  // Visualization/BI tools are typically GOOD_TO_HAVE for data roles
  const biTools = ['looker studio', 'metabase', 'tableau', 'power bi', 'google sheets', 'r shiny'];
  if (biTools.includes(skill)) {
    if (jobTitle.includes('data') || jobTitle.includes('analyst')) {
      goodToHaveSkills.push(skill);
      return;
    } else {
      optionalSkills.push(skill);
      return;
    }
  }

  // Frameworks and libraries are typically GOOD_TO_HAVE or OPTIONAL
  const frameworks = ['react', 'angular', 'vue', 'django', 'flask', 'spring', 'express'];
  if (frameworks.includes(skill)) {
    optionalSkills.push(skill);
    return;
  }

  // If marked as MUST_HAVE, add to that category
  if (isMustHave) {
    mustHaveSkills.push(skill);
  } else {
    // Default: first 30% are GOOD_TO_HAVE, rest are OPTIONAL
    const skillIndex = jdNormalized.indexOf(skill);
    if (skillIndex < jdNormalized.length * 0.3) {
      goodToHaveSkills.push(skill);
    } else {
      optionalSkills.push(skill);
    }
  }
});

// 8. Match skills by category
const matchedMustHave = mustHaveSkills.filter(skill => resumeNormalized.includes(skill));
const matchedGoodToHave = goodToHaveSkills.filter(skill => resumeNormalized.includes(skill));
const matchedOptional = optionalSkills.filter(skill => resumeNormalized.includes(skill));

const missingMustHave = mustHaveSkills.filter(skill => !resumeNormalized.includes(skill));

// 9. Calculate weighted score
const mustHaveScore = matchedMustHave.length * 5;
const goodToHaveScore = matchedGoodToHave.length * 3;
const optionalScore = matchedOptional.length * 1;

const maxPossibleScore = (mustHaveSkills.length * 5) + (goodToHaveSkills.length * 3) + (optionalSkills.length * 1);
const skillScore = maxPossibleScore > 0 ? Math.round((mustHaveScore + goodToHaveScore + optionalScore) / maxPossibleScore * 70) : 0;

// 10. Experience scoring with context
const resumeExperience = resumeData.experience_years || 0;

let experienceScore = 0;
let experienceContext = '';

if (requiredExperience === 0) {
  experienceScore = 15;
  experienceContext = 'No specific experience required';
} else if (resumeExperience >= requiredExperience * 1.5) {
  experienceScore = 20;
  experienceContext = `Significantly exceeds requirement (${resumeExperience} vs ${requiredExperience} years)`;
} else if (resumeExperience >= requiredExperience) {
  experienceScore = 15;
  experienceContext = `Meets requirement (${resumeExperience} vs ${requiredExperience} years)`;
} else if (resumeExperience >= requiredExperience * 0.7) {
  experienceScore = 10;
  experienceContext = `Close to requirement (${resumeExperience} vs ${requiredExperience} years)`;
} else {
  experienceScore = 5;
  experienceContext = `Below requirement (${resumeExperience} vs ${requiredExperience} years)`;
}

// 11. Education bonus
let educationScore = 0;
const resumeEducation = (resumeData.education || '').toLowerCase();
const requiredEducation = (jdData.required_education || '').toLowerCase();

if (requiredEducation && resumeEducation.includes(requiredEducation)) {
  educationScore = 10;
} else if (requiredEducation) {
  educationScore = 5;
}

// 12. Final ATS score
let atsScore = skillScore + experienceScore + educationScore;
if (atsScore > 100) atsScore = 100;

// 13. Confidence level based on missing must-have skills
let confidenceLevel = 'High';
if (missingMustHave.length > 0) {
  confidenceLevel = 'Low';
} else if (matchedGoodToHave.length < goodToHaveSkills.length * 0.5) {
  confidenceLevel = 'Medium';
}

// 14. Fit category
let fitCategory = 'Low Fit';
let sendAlert = false;
if (atsScore >= 75 && missingMustHave.length === 0) {
  fitCategory = 'High Fit';
  sendAlert = true;
} else if (atsScore >= 50) {
  fitCategory = 'Medium Fit';
}

// 15. Generate reasoning summary
const reasoningSummary = [
  `Skill Match: ${matchedMustHave.length}/${mustHaveSkills.length} must-have, ${matchedGoodToHave.length}/${goodToHaveSkills.length} good-to-have, ${matchedOptional.length}/${optionalSkills.length} optional`,
  experienceContext,
  missingMustHave.length > 0 ? `Missing critical skills: ${missingMustHave.join(', ')}` : 'All critical skills matched'
].join('. ');

// 16. Retrieve hashes
const resumeHash = $('Resume Readability Check').item.json.resume_hash || '';
const jdHash = $('Generate JD Hash').item.json.jd_hash || '';

// 17. Return enhanced output with skill categorization
return {
  ...resumeData,
  ...jdData,
  skill_categories: {
    must_have: mustHaveSkills,
    good_to_have: goodToHaveSkills,
    optional: optionalSkills
  },
  matched_skills: {
    must_have: matchedMustHave,
    good_to_have: matchedGoodToHave,
    optional: matchedOptional
  },
  missing_must_have_skills: missingMustHave,
  skill_match_percentage: Math.round(((matchedMustHave.length + matchedGoodToHave.length + matchedOptional.length) / jdNormalized.length) * 100),
  ats_score: atsScore,
  score_breakdown: {
    skill_score: skillScore,
    experience_score: experienceScore,
    education_score: educationScore
  },
  fit_category: fitCategory,
  send_high_fit_alert: sendAlert,
  confidence: confidenceLevel,
  explanation: reasoningSummary,
  evaluated_at: new Date().toISOString(),
  resume_hash: resumeHash,
  jd_hash: jdHash
};
